-- Email intake: each organization forwards mail to <token>@<inbound domain>.
-- The token is generated by the application the first time it is needed.
ALTER TABLE organizations ADD COLUMN inbound_email_token VARCHAR(40);
CREATE UNIQUE INDEX uq_organizations_inbound_email_token ON organizations (inbound_email_token);

-- Where a work item came from, and who to reply to.
ALTER TABLE work_items ADD COLUMN source VARCHAR(20) NOT NULL DEFAULT 'MANUAL';
ALTER TABLE work_items ADD COLUMN sender_email VARCHAR(320);
ALTER TABLE work_items ADD COLUMN sender_name VARCHAR(255);
ALTER TABLE work_items ADD COLUMN subject VARCHAR(1000);

-- Who decided on a proposal, and when.
ALTER TABLE proposed_actions ADD COLUMN decided_by_user_id UUID;
ALTER TABLE proposed_actions ADD COLUMN decided_at TIMESTAMP(6) WITH TIME ZONE;

CREATE TABLE inbound_messages (
    id                 UUID                        NOT NULL PRIMARY KEY,
    organization_id    UUID                        NOT NULL REFERENCES organizations (id),
    work_item_id       UUID                        REFERENCES work_items (id),
    -- Message-ID header, or the provider's id when the header is missing
    dedupe_key         VARCHAR(998)                NOT NULL,
    provider_message_id VARCHAR(255),
    message_id_header  VARCHAR(998),
    in_reply_to        VARCHAR(998),
    references_header  TEXT,
    mailbox_hash       VARCHAR(255),
    from_email         VARCHAR(320),
    from_name          VARCHAR(255),
    to_addresses       TEXT,
    subject            VARCHAR(1000),
    text_body          TEXT,
    reply_text         TEXT,
    is_automated       BOOLEAN                     NOT NULL DEFAULT FALSE,
    received_at        TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    status             VARCHAR(30)                 NOT NULL,
    status_reason      VARCHAR(1000),
    attempts           INTEGER                     NOT NULL DEFAULT 0,
    next_attempt_at    TIMESTAMP(6) WITH TIME ZONE,
    created_at         TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    updated_at         TIMESTAMP(6) WITH TIME ZONE NOT NULL,
    version            BIGINT                      NOT NULL DEFAULT 0,
    CONSTRAINT uq_inbound_messages_dedupe UNIQUE (organization_id, dedupe_key)
);

CREATE INDEX idx_inbound_messages_org_received ON inbound_messages (organization_id, received_at);
CREATE INDEX idx_inbound_messages_status_next ON inbound_messages (status, next_attempt_at);
CREATE INDEX idx_inbound_messages_work_item ON inbound_messages (work_item_id);
CREATE INDEX idx_inbound_messages_message_id ON inbound_messages (organization_id, message_id_header);

CREATE TABLE inbound_attachments (
    id                  UUID         NOT NULL PRIMARY KEY,
    inbound_message_id  UUID         NOT NULL REFERENCES inbound_messages (id),
    file_name           VARCHAR(500),
    content_type        VARCHAR(255),
    size_bytes          BIGINT
);

CREATE INDEX idx_inbound_attachments_message ON inbound_attachments (inbound_message_id);

CREATE TABLE outbound_messages (
    id                   UUID                        NOT NULL PRIMARY KEY,
    organization_id      UUID                        NOT NULL REFERENCES organizations (id),
    work_item_id         UUID                        NOT NULL REFERENCES work_items (id),
    proposed_action_id   UUID                        REFERENCES proposed_actions (id),
    to_email             VARCHAR(320)                NOT NULL,
    subject              VARCHAR(1000)               NOT NULL,
    body                 TEXT                        NOT NULL,
    provider_message_id  VARCHAR(255),
    sent_by_user_id      UUID,
    sent_at              TIMESTAMP(6) WITH TIME ZONE NOT NULL
);

CREATE INDEX idx_outbound_messages_work_item ON outbound_messages (work_item_id);

-- Audit trail of what happened to a work item and who did it.
CREATE TABLE work_item_events (
    id               UUID                        NOT NULL PRIMARY KEY,
    organization_id  UUID                        NOT NULL REFERENCES organizations (id),
    work_item_id     UUID                        NOT NULL REFERENCES work_items (id),
    type             VARCHAR(50)                 NOT NULL,
    detail           TEXT,
    actor_user_id    UUID,
    created_at       TIMESTAMP(6) WITH TIME ZONE NOT NULL
);

CREATE INDEX idx_work_item_events_work_item ON work_item_events (work_item_id, created_at);
